<?php
declare(strict_types=1);require __DIR__.'/v10-lib.php';if(PHP_SAPI!=='cli'){http_response_code(403);exit;}$pdo=db();$dir=v10_storage_dir('backups');if(!class_exists('ZipArchive'))throw new RuntimeException('ZIP extension is required');$companies=$pdo->query('SELECT id FROM companies ORDER BY id')->fetchAll(PDO::FETCH_COLUMN);foreach($companies as$cid){$cid=(int)$cid;$name='daily-'.$cid.'-'.date('Ymd-His').'.zip';$path=$dir.'/'.$name;$tables=$pdo->query("SELECT table_name FROM information_schema.columns WHERE table_schema=DATABASE() AND column_name='company_id' ORDER BY table_name")->fetchAll(PDO::FETCH_COLUMN);$dump=['version'=>APP_VERSION,'company_id'=>$cid,'created_at'=>date(DATE_ATOM),'tables'=>[]];$st=$pdo->prepare('SELECT * FROM companies WHERE id=?');$st->execute([$cid]);$dump['tables']['companies']=$st->fetchAll();foreach($tables as$table){if(!preg_match('/^[A-Za-z0-9_]+$/',$table))continue;$st=$pdo->prepare('SELECT * FROM `'.$table.'` WHERE company_id=?');$st->execute([$cid]);$dump['tables'][$table]=$st->fetchAll();}$z=new ZipArchive();$z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE);$z->addFromString('database.json',json_encode($dump,JSON_UNESCAPED_UNICODE));$uploads=v10_storage_dir('private_uploads').'/'.$cid;if(is_dir($uploads)){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($uploads,FilesystemIterator::SKIP_DOTS));foreach($it as$f)if($f->isFile())$z->addFile($f->getPathname(),'uploads/'.substr($f->getPathname(),strlen($uploads)+1));}$z->close();$pdo->prepare('INSERT INTO v10_backups(company_id,file_name,file_size) VALUES(?,?,?)')->execute([$cid,$name,filesize($path)?:0]);}$files=glob($dir.'/daily-*.zip')?:[];usort($files,fn($a,$b)=>filemtime($b)<=>filemtime($a));foreach(array_slice($files,14)as$f)@unlink($f);echo"backup_ok\n";
